-- Finding a place in the game code by its byte pattern (from source\sites.inc.lua, the same in every script of this
-- project). site = { name, pattern, mark, call, expect } generated by sites.py:
--   pattern  must match exactly once (memreader Plus compares the original bytes under its own hooks and caves)
--   mark     byte offset of the place in the pattern
--   call     the place is the target of the call (E8) at the mark
--   expect   the original bytes at the place (read_original, so a cave of an earlier battle does not hide them)
-- Raises an error (text) when this game build does not fit; only reads.
local function find_site(mr, site)
	local address, count = mr.find_pattern(site.pattern)
	if not address or count ~= 1 then error(('this game build does not fit (the %s code was found %s times, expected 1)'):format(site.name, tostring(count)), 0) end
	local at = mr.add(address, site.mark)
	if site.call then
		local b = mr.read_original(at, 0, 5)
		if type(b) ~= 'string' or #b ~= 5 or string.byte(b, 1) ~= 232 then error('this game build does not fit (no call at the ' .. site.name .. ' code)', 0) end
		local lo = string.byte(b, 2) + string.byte(b, 3) * 256
		local hi = string.byte(b, 4) + string.byte(b, 5) * 256
		if hi >= 32768 then hi = hi - 65536 end
		at = mr.add(mr.add(at, 5 + lo), hi * 65536) -- two exact parts: the game's Lua numbers are 32-bit floats
	end
	if mr.read_original(at, 0, #site.expect) ~= site.expect then error('this game build does not fit (unexpected code at the ' .. site.name .. ')', 0) end
	return at
end
